ange\\nFROM employee\\nGROUP BY salary_range\\nORDER BY FIELD(salary_range, \'5k-8k\', \'8k-12k\', \'12k-16k\', \'16k-20k\', \'20k-30k\', \'30k以上\')\"}, \"result\": {\"rows\": [{\"dept_name\": \"技术部\", \"emp_count\": 1, \"avg_salary\": 50000.0, \"max_salary\": 50000.0, \"min_salary\": 50000.0, \"active_count\": 1, \"total_salary\": 50000.0}, {\"dept_name\": \"后端组\", \"emp_count\": 4, \"avg_salary\": 30500.0, \"max_salary\": 45000.0, \"min_salary\": 23000.0, \"active_count\": 4, \"total_salary\": 122000.0}, {\"dept_name\": \"财务部\", \"emp_count\": 1, \"avg_salary\": 30000.0, \"max_salary\": 30000.0, \"min_salary\": 30000.0, \"active_count\": 1, \"total_salary\": 30000.0}, {\"dept_name\": \"人力资源部\", \"emp_count\": 1, \"avg_salary\": 28000.0, \"max_salary\": 28000.0, \"min_salary\": 28000.0, \"active_count\": 1, \"total_salary\": 28000.0}, {\"dept_name\": \"产品部\", \"emp_count\": 2, \"avg_salary\": 25000.0, \"max_salary\": 32000.0, \"min_salary\": 18000.0, \"active_count\": 2, \"total_salary\": 50000.0}, {\"dept_name\": \"销售部\", \"emp_count\": 4, \"avg_salary\": 21000.0, \"max_salary\": 35000.0, \"min_salary\": 15000.0, \"active_count\": 3, \"total_salary\": 84000.0}, {\"dept_name\": \"测试组\", \"emp_count\": 2, \"avg_salary\": 19500.0, \"max_salary\": 20000.0, \"min_salary\": 19000.0, \"active_count\": 2, \"total_salary\": 39000.0}, {\"dept_name\": \"前端组\", \"emp_count\": 3, \"avg_salary\": 19333.33, \"max_salary\": 28000.0, \"min_salary\": 8000.0, \"active_count\": 3, \"total_salary\": 58000.0}, {\"dept_name\": \"市场部\", \"emp_count\": 2, \"avg_salary\": 18500.0, \"max_salary\": 20000.0, \"min_salary\": 17000.0, \"active_count\": 1, \"total_salary\": 37000.0}], \"summary\": \"查询返回 9 行:\\n\\n| dept_name | emp_count | active_count | avg_salary | max_salary | min_salary | total_salary |\\n| --- | --- | --- | --- | --- | --- | --- |\\n| 技术部 | 1 | 1 | 50000.00 | 50000.00 | 50000.00 | 50000.00 | \\n| 后端组 | 4 | 4 | 30500.00 | 45000.00 | 23000.00 | 122000.00 | \\n| 财务部 | 1 | 1 | 