it(X, y, test_size=0.2, random_state=42)\\n\\nprint(f\\\"训练集: {len(X_train)} 条, 测试集: {len(X_test)} 条\\\")\\n\\n# 训练决策树回归模型\\nmodel = DecisionTreeRegressor(max_depth=5, min_samples_split=2, min_samples_leaf=1, random_state=42)\\nmodel.fit(X_train, y_train)\\n\\n# 预测\\ny_pred = model.predict(X_test)\\n\\n# 评估\\nmse = mean_squared_error(y_test, y_pred)\\nrmse = np.sqrt(mse)\\nmae = mean_absolute_error(y_test, y_pred)\\nr2 = r2_score(y_test, y_pred)\\n\\nprint(f\\\"\\\\n📊 模型评估结果:\\\")\\nprint(f\\\"MSE:  {mse:.2f}\\\")\\nprint(f\\\"RMSE: {rmse:.2f}\\\")\\nprint(f\\\"MAE:  {mae:.2f}\\\")\\nprint(f\\\"R²:   {r2:.4f}\\\")\\n\\n# 特征重要性\\nimportance = pd.DataFrame({\\n    \'feature\': features,\\n    \'importance\': model.feature_importances_\\n}).sort_values(\'importance\', ascending=False)\\nprint(f\\\"\\\\n🔍 特征重要性排名:\\\")\\nprint(importance.to_string(index=False))\\n\\n# 训练集评估\\ny_train_pred = model.predict(X_train)\\nr2_train = r2_score(y_train, y_train_pred)\\nprint(f\\\"\\\\n训练集 R²: {r2_train:.4f}\\\")\\nprint(f\\\"测试集 R²: {r2:.4f}\\\")\\n\"}, \"result\": {\"stderr\": \"\", \"stdout\": \"训练集: 26 条, 测试集: 7 条\\n\\n📊 模型评估结果:\\nMSE:  17598.81\\nRMSE: 132.66\\nMAE:  120.60\\nR²:   -5.2194\\n\\n🔍 特征重要性排名:\\n            feature  importance\\noutstanding_balance    0.369403\\n    monthly_payment    0.212580\\n      interest_rate    0.192806\\n   loan_term_months    0.117948\\n        loan_amount    0.102857\\ncollateral_type_enc    0.004406\\n     overdue_months    0.000000\\n\\n训练集 R²: 0.7229\\n测试集 R²: -5.2194\\n\", \"exitCode\": 0, \"artifacts\": []}, \"status\": \"success\"}, {\"_id\": \"py-410763458313208\", \"name\": \"execute_python\", \"type\": \"tool_use\", \"input\": {\"code\": \"\\n# 数据量太小(33条)导致模型泛化能力差\\n# 尝试用全部数据训练，并用交叉验证评估\\nfrom sklearn.tree import DecisionTreeRegressor\\nfrom sklearn.model_selection import cross_val_score, KFold\\nfrom sklearn.preprocessing import LabelEncoder\\nimport numpy as np\\n\\ndf = pd.read_sql(\\\"SELECT loan_amount,interest_rate,loan_term_months,monthly_payment,outstanding_balance,overdue_months,collateral_type,credit_score FROM loan\\\", engine)\\n\\nle = LabelEncoder()\\ndf[\'collateral_type_enc\'] = le.fit_transform(df[\'collateral_type\'])\\n\\nfeatures = [\'loan_amount\',\'interest_rate\',\'loan_term_months\',\'monthly_payment\',\'outstanding_balance\',\'overdue_months\',\'collateral_type_enc\']\\nX = df[features].values\\ny = df[\'credit_score\'].values\\n\\n# 5折交叉验证\\nmodel = DecisionTreeRegressor(max_depth=3, min_samples_leaf=3, random_state=42)\\nkf = KFold(n_splits=5, shuffle=True, random_state=42)\\nscores = cross_val_score(model, X, y, cv=kf, scoring=\'r2\')\\n\\nprint(f\\\"5折交叉验证 R² 得分: {scores}\\\")\\nprint(f\\\"平均 R²: {scores.mean():.4f} (±{scores.std():.4f})\\\")\\n\\n# 用更保守的参数\\nmodel2 = DecisionTreeRegressor(max_depth=4, min_samples_leaf=5, random_state=42)\\nscores2 = cross_val_score(model2, X, y, cv=kf, scoring=\'r2\')\\nprint(f\\\"\\\\n保守参数(max_depth=4, min_leaf=5):\\\")\\nprint(f\\\"5折交叉验证 R² 得分: {scores2}\\\")\\nprint(f\\\"平均 R²: {scores2.mean():.4f} (±{scores2.std():.4f})\\\")\\n\\n# 用全量数据训练最终模型\\nfinal_model = DecisionTreeRegressor(max_depth=3, min_samples_leaf=3, random_state=42)\\nfinal_model.fit(X, y)\\n\\nimportance = pd.DataFrame({\\n    \'feature\': features,\\n    \'importance\': final_model.feature_importances_\\n}).sort_values(\'importance\', ascending=False)\\nprint(f\\\"\\\\n🔍 最终模型特征重要性:\\\")\\nprint(importance.to_string(index=False))\\n\\nprint(f\\\"\\\\n训练集 R²: {r2_score(y, final_model.predict(X)):.4f}\\\")\\n\"}, \"result\": {\"stderr\": \"Traceback (most recent call last):\\n  File \\\"/var/folders/j4/czgrwyn517v0sk3vq44j06mc0000gn/T/smartquery_4553495258965657409.py\\\", line 89, in <module>\\n    print(f\\\"\\\\n训练集 R²: {r2_score(y, final_model.predict(X)):.4f}\\\")\\nNameError: name \'r2_score\' is not defined\\n\", \"stdout\": \"5折交叉验证 R² 得分: [-2.26490565 -0.60610338 -2.04701864 -0.21105848  0.28532146]\\n平均 R²: -0.9688 (±1.0120)\\n\\n保守参数(max_depth=4, m