CREATE TABLE `sq_algorithm` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `algorithm_id` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '唯一标识符',
  `name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '显示名称',
  `description` text COLLATE utf8mb4_unicode_ci COMMENT '算法描述',
  `model_types` json NOT NULL COMMENT '支持的模型类型 ["classification","regression"]',
  `params_schema` json NOT NULL COMMENT '参数定义数组',
  `python_code_template` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'Python训练代码模板',
  `is_builtin` tinyint NOT NULL DEFAULT '0' COMMENT '1=内置 0=自定义',
  `icon` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '图标emoji',
  `category` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '分类(用于面板分组)',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_algorithm_id` (`algorithm_id`)
) ENGINE=InnoDB AUTO_INCREMENT=10 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

