INSERT INTO `sq_algorithm` (`id`, `algorithm_id`, `name`, `description`, `model_types`, `params_schema`, `python_code_template`, `is_builtin`, `icon`, `category`, `created_at`, `updated_at`, `deleted`) VALUES (1,'random_forest','随机森林','集成学习方法，通过构建多棵决策树提高预测精度和稳定性','[\"classification\", \"regression\"]','[{\"key\": \"n_estimators\", \"max\": 1000, \"min\": 1, \"hint\": \"n_estimators\", \"step\": 1, \"type\": \"int\", \"label\": \"树的数量\", \"defaultValue\": 100}, {\"key\": \"max_depth\", \"max\": 100, \"min\": 1, \"hint\": \"max_depth\", \"step\": 1, \"type\": \"int\", \"label\": \"最大深度\", \"defaultValue\": 10}, {\"key\": \"min_samples_split\", \"max\": 100, \"min\": 2, \"hint\": \"min_samples_split\", \"step\": 1, \"type\": \"int\", \"label\": \"最小分裂样本数\", \"defaultValue\": 2}, {\"key\": \"min_samples_leaf\", \"max\": 50, \"min\": 1, \"hint\": \"min_samples_leaf\", \"step\": 1, \"type\": \"int\", \"label\": \"叶节点最小样本数\", \"defaultValue\": 1}, {\"key\": \"class_weight\", \"hint\": \"class_weight\", \"type\": \"select\", \"label\": \"类别权重\", \"options\": [\"balanced\", \"balanced_subsample\", \"None\"], \"defaultValue\": \"balanced\"}]','from sklearn.ensemble import RandomForestClassifier, RandomForestRegressor\nmodel_cls = RandomForestClassifier if _model_type == \'classification\' else RandomForestRegressor\nclf = model_cls(**params)',1,'🌲','分类/回归','2026-05-14 22:30:40','2026-05-15 08:26:04',0),(2,'xgboost','XGBoost','高效梯度提升算法，适合结构化数据的分类和回归任务','[\"classification\", \"regression\"]','[{\"key\": \"n_estimators\", \"max\": 1000, \"min\": 1, \"hint\": \"n_estimators\", \"step\": 1, \"type\": \"int\", \"label\": \"树的数量\", \"defaultValue\": 100}, {\"key\": \"max_depth\", \"max\": 50, \"min\": 1, \"hint\": \"max_depth\", \"step\": 1, \"type\": \"int\", \"label\": \"最大深度\", \"defaultValue\": 6}, {\"key\": \"learning_rate\", \"max\": 1, \"min\": 0.001, \"hint\": \"learning_rate\", \"step\": 0.01, \"type\": \"float\", \"label\": \"学习率\", \"defaultValue\": 0.3}, {\"key\": \"subsample\", \"max\": 1, \"min\": 0.1, \"hint\": \"subsample\", \"step\": 0.1, \"type\": \"float\", \"label\": \"子采样率\", \"defaultValue\": 1}, {\"key\": \"colsample_bytree\", \"max\": 1, \"min\": 0.1, \"hint\": \"colsample_bytree\", \"step\": 0.1, \"type\": \"float\", \"label\": \"特征采样率\", \"defaultValue\": 1}, {\"key\": \"scale_pos_weight\", \"max\": 100, \"min\": 1, \"hint\": \"scale_pos_weight\", \"step\": 1, \"type\": \"float\", \"label\": \"正样本权重\", \"defaultValue\": 1}]','from xgboost import XGBClassifier, XGBRegressor\nmodel_cls = XGBClassifier if _model_type == \'classification\' else XGBRegressor\nclf = model_cls(**params)',1,'📈','分类/回归','2026-05-14 22:30:40','2026-05-15 08:25:27',0),(3,'decision_tree','决策树','基于特征进行递归分裂的树模型，可解释性强','[\"classification\", \"regression\"]','[{\"key\": \"max_depth\", \"max\": 100, \"min\": 1, \"hint\": \"max_depth\", \"step\": 1, \"type\": \"int\", \"label\": \"最大深度\", \"defaultValue\": 10}, {\"key\": \"min_samples_split\", \"max\": 100, \"min\": 2, \"hint\": \"min_samples_split\", \"step\": 1, \"type\": \"int\", \"label\": \"最小分裂样本数\", \"defaultValue\": 2}, {\"key\": \"criterion\", \"hint\": \"criterion\", \"type\": \"select\", \"label\": \"分裂标准\", \"options\": [\"gini\", \"entropy\"], \"defaultValue\": \"gini\"}]','from sklearn.tree import DecisionTreeClassifier, DecisionTreeRegressor\nmodel_cls = DecisionTreeClassifier if _model_type == \'classification\' else DecisionTreeRegressor\nclf = model_cls(**params)',1,'🌳','分类/回归','2026-05-14 22:30:40','2026-05-15 06:22:07',0),(4,'logistic_regression','逻辑回归','线性分类模型，适合二分类和多分类任务','[\"classification\"]','[{\"key\": \"C\", \"max\": 100, \"min\": 0.01, \"hint\": \"C\", \"step\": 0.1, \"type\": \"float\", \"label\": \"正则化强度\", \"defaultValue\": 1}, {\"key\": \"max_iter\", \"max\": 10000, \"min\": 10, \"hint\": \"max_iter\", \"step\": 1, \"type\": \"int\", \"label\": \"最大迭代次数\", \"defaultValue\": 100}, {\"key\": \"solver\", \"hint\": \"solver\", \"type\": \"select\", \"label\": \"求解器\", \"options\": [\"lbfgs\", \"liblinear\", \"saga\"], \"defaultValue\": \"lbfgs\"}]','from sklearn.linear_model import LogisticRegression\nfrom sklearn.preprocessing import StandardScaler\nscaler = StandardScaler()\nX = pd.DataFrame(scaler.fit_transform(X), columns=X.columns)\nclf = LogisticRegression(**params)',1,'📐','分类','2026-05-14 22:30:40','2026-05-14 22:30:40',0),(5,'svm','支持向量机','通过寻找最优超平面进行分类，适合中小规模数据集','[\"classification\", \"regression\"]','[{\"key\": \"C\", \"max\": 100, \"min\": 0.01, \"hint\": \"C\", \"step\": 0.1, \"type\": \"float\", \"label\": \"正则化强度\", \"defaultValue\": 1}, {\"key\": \"kernel\", \"hint\": \"kernel\", \"type\": \"select\", \"label\": \"核函数\", \"options\": [\"rbf\", \"linear\", \"poly\"], \"defaultValue\": \"rbf\"}, {\"key\": \"gamma\", \"hint\": \"gamma\", \"type\": \"select\", \"label\": \"Gamma\", \"options\": [\"scale\", \"auto\"], \"defaultValue\": \"scale\"}]','from sklearn.svm import SVC, SVR\nmodel_cls = SVC if _model_type == \'classification\' else SVR\nclf = model_cls(**params)',1,'🔶','分类/回归','2026-05-14 22:30:40','2026-05-15 06:22:07',0),(6,'knn','K近邻','基于距离度量的惰性学习算法，简单直观','[\"classification\", \"regression\"]','[{\"key\": \"n_neighbors\", \"max\": 100, \"min\": 1, \"hint\": \"n_neighbors\", \"step\": 1, \"type\": \"int\", \"label\": \"邻居数 K\", \"defaultValue\": 5}, {\"key\": \"weights\", \"hint\": \"weights\", \"type\": \"select\", \"label\": \"权重\", \"options\": [\"uniform\", \"distance\"], \"defaultValue\": \"uniform\"}]','from sklearn.neighbors import KNeighborsClassifier, KNeighborsRegressor\nmodel_cls = KNeighborsClassifier if _model_type == \'classification\' else KNeighborsRegressor\nclf = model_cls(**params)',1,'🔗','分类/回归','2026-05-14 22:30:40','2026-05-15 06:22:07',0),(7,'gradient_boosting','梯度提升','串行构建弱学习器的集成方法，预测精度高','[\"classification\", \"regression\"]','[{\"key\": \"n_estimators\", \"max\": 1000, \"min\": 1, \"hint\": \"n_estimators\", \"step\": 1, \"type\": \"int\", \"label\": \"树的数量\", \"defaultValue\": 100}, {\"key\": \"max_depth\", \"max\": 50, \"min\": 1, \"hint\": \"max_depth\", \"step\": 1, \"type\": \"int\", \"label\": \"最大深度\", \"defaultValue\": 3}, {\"key\": \"learning_rate\", \"max\": 1, \"min\": 0.001, \"hint\": \"learning_rate\", \"step\": 0.01, \"type\": \"float\", \"label\": \"学习率\", \"defaultValue\": 0.1}, {\"key\": \"subsample\", \"max\": 1, \"min\": 0.1, \"hint\": \"subsample\", \"step\": 0.1, \"type\": \"float\", \"label\": \"子采样率\", \"defaultValue\": 1}]','from sklearn.ensemble import GradientBoostingClassifier, GradientBoostingRegressor\nmodel_cls = GradientBoostingClassifier if _model_type == \'classification\' else GradientBoostingRegressor\nclf = model_cls(**params)',1,'🚀','分类/回归','2026-05-14 22:30:40','2026-05-15 08:25:27',0),(8,'lightgbm','LightGBM','微软开源的快速梯度提升框架，训练速度快、内存占用低','[\"classification\", \"regression\"]','[{\"key\": \"n_estimators\", \"max\": 1000, \"min\": 1, \"hint\": \"n_estimators\", \"step\": 1, \"type\": \"int\", \"label\": \"树的数量\", \"defaultValue\": 100}, {\"key\": \"max_depth\", \"max\": 50, \"min\": -1, \"hint\": \"max_depth(-1为无限制)\", \"step\": 1, \"type\": \"int\", \"label\": \"最大深度\", \"defaultValue\": -1}, {\"key\": \"learning_rate\", \"max\": 1, \"min\": 0.001, \"hint\": \"learning_rate\", \"step\": 0.01, \"type\": \"float\", \"label\": \"学习率\", \"defaultValue\": 0.1}, {\"key\": \"num_leaves\", \"max\": 256, \"min\": 2, \"hint\": \"num_leaves\", \"step\": 1, \"type\": \"int\", \"label\": \"叶子节点数\", \"defaultValue\": 31}, {\"key\": \"subsample\", \"max\": 1, \"min\": 0.1, \"hint\": \"subsample\", \"step\": 0.1, \"type\": \"float\", \"label\": \"子采样率\", \"defaultValue\": 1}, {\"key\": \"scale_pos_weight\", \"max\": 100, \"min\": 1, \"hint\": \"scale_pos_weight\", \"step\": 1, \"type\": \"float\", \"label\": \"正样本权重\", \"defaultValue\": 1}]','from lightgbm import LGBMClassifier, LGBMRegressor\nmodel_cls = LGBMClassifier if _model_type == \'classification\' else LGBMRegressor\nclf = model_cls(**params)',1,'💡','分类/回归','2026-05-14 22:30:40','2026-05-15 08:26:24',0),(9,'kmeans','K-Means 聚类','基于距离的无监督聚类算法，将数据分为K个簇','[\"clustering\"]','[{\"key\": \"n_clusters\", \"max\": 50, \"min\": 2, \"hint\": \"n_clusters\", \"step\": 1, \"type\": \"int\", \"label\": \"聚类数\", \"defaultValue\": 3}, {\"key\": \"max_iter\", \"max\": 1000, \"min\": 10, \"hint\": \"max_iter\", \"step\": 1, \"type\": \"int\", \"label\": \"最大迭代次数\", \"defaultValue\": 300}]','from sklearn.cluster import KMeans\nparams.setdefault(\'n_clusters\', 3)\nclf = KMeans(**params)',1,'🎯','聚类','2026-05-14 22:30:40','2026-05-14 22:30:40',0);
/*!40000 ALTER TABLE `sq_algorithm` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `sq_mining_model`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sq_mining_model` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `pipeline_id` bigint DEFAULT NULL COMMENT '关联流水线',
  `name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `description` text COLLATE utf8mb4_unicode_ci,
  `data_source_id` bigint NOT NULL,
  `conversation_id` bigint DEFAULT NULL COMMENT '来源对话ID',
  `model_type` varchar(50) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'classification/regression/clustering/anomaly_detection',
  `algorithm` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'random_forest/xgboost/kmeans/...',
  `source_table` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '源数据表',
  `feature_columns` json DEFAULT NULL COMMENT '特征列',
  `target_column` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '目标列',
  `preprocessing` json DEFAULT NULL COMMENT '预处理配置',
  `hyperparameters` json NOT NULL COMMENT '算法超参数 {n_estimators:100, max_depth:5, ...}',
  `metrics` json DEFAULT NULL COMMENT '评估指标 {accuracy:0.95, f1:0.93, ...}',
  `feature_importance` json DEFAULT NULL COMMENT '特征重要性',
  `training_log` text COLLATE utf8mb4_unicode_ci COMMENT '训练日志',
  `model_path` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '持久化模型路径(.pkl)',
  `status` enum('draft','training','trained','published','offline','failed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'draft',
  `version` int NOT NULL DEFAULT '1',
  `schedule_cron` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '调度cron表达式',
  `schedule_enabled` tinyint NOT NULL DEFAULT '0',
  `last_run_at` datetime DEFAULT NULL,
  `next_run_at` datetime DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` tinyint NOT NULL DEFAULT '0',
  `predict_input_table` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '批量预测：输入数据表',
  `predict_result_table` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '批量预测：结果保存表',
  `schedule_mode` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'train' COMMENT '调度模式: train=定期重训, predict=定期预测',
  `predict_input_filter` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '批量预测输入筛选条件，支持变量: etl_date/today/yesterday/today-N',
  `validation_mode` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT 'train_test' COMMENT 'train_test / cv / oos / temporal',
  `cv_folds` int DEFAULT '5' COMMENT '交叉验证折数',
  `test_size` double DEFAULT '0.2' COMMENT '测试集比例',
  `temporal_column` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '时间列(用于时序验证)',
  `validation_metrics` text COLLATE utf8mb4_unicode_ci COMMENT '验证指标JSON(样本外/时序验证结果)',
  PRIMARY KEY (`id`),
  KEY `idx_pipeline` (`pipeline_id`),
  KEY `idx_datasource` (`data_source_id`),
  KEY `idx_conversation` (`conversation_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=52 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `sq_mining_model` WRITE;
/*!40000 ALTER TABLE `sq_mining_model` DISABLE KEYS */;
