CREATE TABLE `sq_prediction_result` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `model_id` bigint NOT NULL COMMENT '关联模型ID',
  `model_name` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '模型名称(冗余)',
  `batch_id` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '批量预测批次ID',
  `input_data` json DEFAULT NULL COMMENT '输入特征值',
  `prediction` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '预测结果',
  `probability` double DEFAULT NULL COMMENT '预测概率/置信度',
  `result_table` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '结果写入的业务表名',
  `predicted_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '预测时间',
  PRIMARY KEY (`id`),
  KEY `idx_model` (`model_id`),
  KEY `idx_batch` (`batch_id`),
  KEY `idx_predicted` (`predicted_at`)
) ENGINE=InnoDB AUTO_INCREMENT=37 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
