DROP TABLE IF EXISTS `sq_python_execution`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sq_python_execution` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `conversation_id` bigint NOT NULL,
  `message_id` bigint DEFAULT NULL,
  `code` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `stdout` text COLLATE utf8mb4_unicode_ci,
  `stderr` text COLLATE utf8mb4_unicode_ci,
  `exit_code` int DEFAULT NULL,
  `execution_time_ms` int DEFAULT NULL,
  `status` enum('pending','running','success','error','timeout') COLLATE utf8mb4_unicode_ci DEFAULT 'pending',
  `data_source_id` bigint DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_conversation_id` (`conversation_id`)
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

