INSERT INTO `sq_python_execution` (`id`, `conversation_id`, `message_id`, `code`, `stdout`, `stderr`, `exit_code`, `execution_time_ms`, `status`, `data_source_id`, `created_at`) VALUES (1,4,NULL,'\nimport pandas as pd\nimport numpy as np\nimport matplotlib\nmatplotlib.use(\'Agg\')\nimport matplotlib.pyplot as plt\nfrom sqlalchemy import text\n\n# 设置中文字体\nplt.rcParams[\'font.sans-serif\'] = [\'SimHei\', \'DejaVu Sans\']\nplt.rcParams[\'axes.unicode_minus\'] = False\n\n# 读取数据\ndf = pd.read_sql(\"\"\"\n    SELECT e.name, e.salary, e.position, e.status, d.name AS dept_name\n    FROM employee e\n    LEFT JOIN department d ON e.dept_id = d.id\n    ORDER BY e.salary DESC\n\"\"\", engine)\n\nprint(\"=\" * 60)\nprint(\"📋 员工薪资数据一览\")\nprint(\"=\" * 60)\nprint(df[[\'name\', \'dept_name\', \'position\', \'salary\']].to_string(index=False))\n\n# ========== 全公司薪资统计分析 ==========\nsalaries = df[\'salary\'].dropna()\n\nprint(\"\\n\" + \"=\" * 60)\nprint(\"📊 全公司薪资统计分析\")\nprint(\"=\" * 60)\n\n# 基本统计量\nmean_val = salaries.mean()\nmedian_val = salaries.median()\nstd_val = salaries.std()\nmin_val = salaries.min()\nmax_val = salaries.max()\nq1 = salaries.quantile(0.25)\nq3 = salaries.quantile(0.75)\niqr = q3 - q1\nskewness = salaries.skew()\nkurtosis = salaries.kurtosis()\ncount = len(salaries)\ntotal = salaries.sum()\n\nprint(f\"  员工人数:       {count} 人\")\nprint(f\"  薪资总和:       ¥{total:,.2f}\")\nprint(f\"  ─────────────────────────────\")\nprint(f\"  均值 (Mean):    ¥{mean_val:,.2f}\")\nprint(f\"  中位数 (Median):¥{median_val:,.2f}\")\nprint(f\"  标准差 (Std):   ¥{std_val:,.2f}\")\nprint(f\"  ─────────────────────────────\")\nprint(f\"  最低薪资:       ¥{min_val:,.2f}\")\nprint(f\"  25%分位数 (Q1): ¥{q1:,.2f}\")\nprint(f\"  75%分位数 (Q3): ¥{q3:,.2f}\")\nprint(f\"  最高薪资:       ¥{max_val:,.2f}\")\nprint(f\"  四分位距 (IQR): ¥{iqr:,.2f}\")\nprint(f\"  ─────────────────────────────\")\nprint(f\"  偏度 (Skewness): {skewness:.4f}\")\nprint(f\"  峰度 (Kurtosis): {kurtosis:.4f}\")\nprint(f\"  变异系数 (CV):   {(std_val/mean_val)*100:.2f}%\")\n\n# ========== 按部门统计 ==========\nprint(\"\\n\" + \"=\" * 60)\nprint(\"📊 各部门薪资统计\")\nprint(\"=\" * 60)\ndept_stats = df.groupby(\'dept_name\')[\'salary\'].agg([\'count\', \'mean\', \'median\', \'std\', \'min\', \'max\'])\ndept_stats.columns = [\'人数\', \'平均薪资\', \'中位数\', \'标准差\', \'最低\', \'最高\']\ndept_stats = dept_stats.sort_values(\'平均薪资\', ascending=False)\nprint(dept_stats.to_string())\n\n# ========== 薪资区间分布 ==========\nprint(\"\\n\" + \"=\" * 60)\nprint(\"📊 薪资区间分布\")\nprint(\"=\" * 60)\nbins = [0, 5000, 8000, 10000, 15000, 20000, float(\'inf\')]\nlabels = [\'5K以下\', \'5K-8K\', \'8K-10K\', \'10K-15K\', \'15K-20K\', \'20K以上\']\ndf[\'salary_range\'] = pd.cut(df[\'salary\'], bins=bins, labels=labels)\nrange_dist = df[\'salary_range\'].value_counts().sort_index()\nfor r, c in range_dist.items():\n    pct = c / len(df) * 100\n    bar = \'█\' * int(pct / 2) + \'░\' * (25 - int(pct / 2))\n    print(f\"  {r:>10s} │{bar}│ {c:2d}人 ({pct:5.1f}%)\")\n','============================================================\n📋 员工薪资数据一览\n============================================================\nname dept_name position  salary\n  陈刚       技术部     技术总监 50000.0\n  张明       后端组      架构师 45000.0\n  王芳       销售部     销售经理 35000.0\n  周明       产品部     产品经理 32000.0\n  王强       后端组  高级后端工程师 30000.0\n  钱伟       财务部     财务主管 30000.0\n  张伟       前端组  高级前端工程师 28000.0\n  孙红     人力资源部     HR经理 28000.0\n  赵敏       后端组    后端工程师 24000.0\n  刘洋       后端组    后端工程师 23000.0\n  李娜       前端组    前端工程师 22000.0\n  陈静       测试组    测试工程师 20000.0\n  林莉       市场部       离职 20000.0\n  杨帆       测试组    测试工程师 19000.0\n  吴丽       产品部     产品助理 18000.0\n  黄磊       销售部       离职 18000.0\n  郑浩       市场部     市场专员 17000.0\n  赵磊       销售部     销售代表 16000.0\n  李强       销售部     销售代表 15000.0\n  韩梅       前端组    前端实习生  8000.0\n\n============================================================\n📊 全公司薪资统计分析\n============================================================\n  员工人数:       20 人\n  薪资总和:       ¥498,000.00\n  ─────────────────────────────\n  均值 (Mean):    ¥24,900.00\n  中位数 (Median):¥22,500.00\n  标准差 (Std):   ¥10,192.36\n  ─────────────────────────────\n  最低薪资:       ¥8,000.00\n  25%分位数 (Q1): ¥18,000.00\n  75%分位数 (Q3): ¥30,000.00\n  最高薪资:       ¥50,000.00\n  四分位距 (IQR): ¥12,000.00\n  ─────────────────────────────\n  偏度 (Skewness): 0.9678\n  峰度 (Kurtosis): 1.0324\n  变异系数 (CV):   40.93%\n\n============================================================\n📊 各部门薪资统计\n============================================================\n           人数          平均薪资      中位数           标准差       最低       最高\ndept_name                                                           \n技术部         1  50000.000000  50000.0           NaN  50000.0  50000.0\n后端组         4  30500.000000  27000.0  10148.891565  23000.0  45000.0\n财务部         1  30000.000000  30000.0           NaN  30000.0  30000.0\n人力资源部       1  28000.000000  28000.0           NaN  28000.0  28000.0\n产品部         2  25000.000000  25000.0   9899.494937  18000.0  32000.0\n销售部         4  21000.000000  17000.0   9416.297928  15000.0  35000.0\n测试组         2  19500.000000  19500.0    707.106781  19000.0  20000.0\n前端组         3  19333.333333  22000.0  10263.202879   8000.0  28000.0\n市场部         2  18500.000000  18500.0   2121.320344  17000.0  20000.0\n\n============================================================\n📊 薪资区间分布\n============================================================\n        5K以下 │░░░░░░░░░░░░░░░░░░░░░░░░░│  0人 (  0.0%)\n       5K-8K │██░░░░░░░░░░░░░░░░░░░░░░░│  1人 (  5.0%)\n      8K-10K │░░░░░░░░░░░░░░░░░░░░░░░░░│  0人 (  0.0%)\n     10K-15K │██░░░░░░░░░░░░░░░░░░░░░░░│  1人 (  5.0%)\n     15K-20K │█████████████████░░░░░░░░│  7人 ( 35.0%)\n       20K以上 │███████████████████████████│ 11人 ( 55.0%)\n','',0,1144,'success',2,'2026-05-13 09:22:26'),(2,8,NULL,'\nimport pandas as pd\nimport numpy as np\nfrom sklearn.linear_model import LinearRegression\nfrom sklearn.metrics import r2_score, mean_squared_error, mean_absolute_error\nfrom scipy import stats\nimport matplotlib\nmatplotlib.use(\'Agg\')\nimport matplotlib.pyplot as plt\nfrom sqlalchemy import text\n\n# 读取数据\ndf = pd.read_sql(\"SELECT name, position, salary, hire_date, dept_id FROM employee WHERE status = 1 ORDER BY hire_date\", engine)\n\n# 计算司龄（以月为单位）\ndf[\'hire_date\'] = pd.to_datetime(df[\'hire_date\'])\nreference_date = pd.Timestamp(\'2026-05-13\')\ndf[\'tenure_months\'] = ((reference_date - df[\'hire_date\']).dt.days / 30.44).round(1)\n\nprint(\"=\" * 60)\nprint(\"📋 员工数据概览\")\nprint(\"=\" * 60)\nprint(df[[\'name\', \'position\', \'salary\', \'hire_date\', \'tenure_months\']].to_string(index=False))\nprint(f\"\\n总人数: {len(df)}\")\n\n# 线性回归：司龄（月） → 薪资\nX = df[\'tenure_months\'].values.reshape(-1, 1)\ny = df[\'salary\'].values\n\nmodel = LinearRegression()\nmodel.fit(X, y)\n\ny_pred = model.predict(X)\n\n# 回归参数\nslope = model.coef_[0]\nintercept = model.intercept_\nr2 = r2_score(y, y_pred)\nrmse = np.sqrt(mean_squared_error(y, y_pred))\nmae = mean_absolute_error(y, y_pred)\n\n# 皮尔逊相关系数\ncorr, p_value = stats.pearsonr(df[\'tenure_months\'], df[\'salary\'])\n\nprint(\"\\n\" + \"=\" * 60)\nprint(\"📈 线性回归分析结果\")\nprint(\"=\" * 60)\nprint(f\"  回归方程:  薪资 = {slope:.2f} × 司龄(月) + {intercept:.2f}\")\nprint(f\"  斜率(β₁):  {slope:.2f} 元/月 （每多工作1个月，薪资平均增加 ¥{slope:.2f}）\")\nprint(f\"  截距(β₀):  ¥{intercept:.2f}\")\nprint(f\"  相关系数 r:  {corr:.4f}\")\nprint(f\"  决定系数 R²:  {r2:.4f} （模型解释了 {r2*100:.1f}% 的薪资变异）\")\nprint(f\"  P值:          {p_value:.6f}\")\nprint(f\"  RMSE:         ¥{rmse:.2f}\")\nprint(f\"  MAE:          ¥{mae:.2f}\")\n\n# 显著性判断\nalpha = 0.05\nif p_value < alpha:\n    print(f\"\\n  ✅ 结论: P值({p_value:.6f}) < 0.05，司龄对薪资的线性影响 **统计显著**\")\nelse:\n    print(f\"\\n  ❌ 结论: P值({p_value:.6f}) >= 0.05，司龄对薪资的线性影响 **不显著**\")\n\n# 预测示例\nprint(\"\\n\" + \"=\" * 60)\nprint(\"🔮 薪资预测示例\")\nprint(\"=\" * 60)\nfor months in [12, 24, 36, 48, 60]:\n    pred_salary = slope * months + intercept\n    print(f\"  司龄 {months:2d} 个月 (≈{months/12:.1f}年) → 预测薪资: ¥{pred_salary:,.2f}\")\n\n# 残差分析\ndf[\'predicted\'] = y_pred\ndf[\'residual\'] = y - y_pred\nprint(\"\\n\" + \"=\" * 60)\nprint(\"📊 残差分析（实际值 vs 预测值）\")\nprint(\"=\" * 60)\nprint(df[[\'name\', \'salary\', \'predicted\', \'residual\']].to_string(index=False))\nprint(f\"\\n  残差均值:  ¥{df[\'residual\'].mean():.2f}\")\nprint(f\"  残差标准差: ¥{df[\'residual\'].std():.2f}\")\n','============================================================\n📋 员工数据概览\n============================================================\nname position  salary  hire_date  tenure_months\n  陈刚     技术总监 50000.0 2017-06-01          107.4\n  张明      架构师 45000.0 2018-01-10          100.0\n  王芳     销售经理 35000.0 2019-05-10           84.1\n  钱伟     财务主管 30000.0 2019-08-15           80.9\n  孙红     HR经理 28000.0 2020-03-01           74.4\n  周明     产品经理 32000.0 2020-11-01           66.3\n  王强  高级后端工程师 30000.0 2021-06-20           58.7\n  张伟  高级前端工程师 28000.0 2022-03-15           49.9\n  陈静    测试工程师 20000.0 2022-09-01           44.3\n  李娜    前端工程师 22000.0 2023-01-10           40.0\n  赵敏    后端工程师 24000.0 2023-03-05           38.3\n  杨帆    测试工程师 19000.0 2023-04-18           36.8\n  刘洋    后端工程师 23000.0 2023-07-12           34.0\n  郑浩     市场专员 17000.0 2023-08-20           32.8\n  赵磊     销售代表 16000.0 2023-11-20           29.7\n  吴丽     产品助理 18000.0 2024-01-15           27.9\n  李强     销售代表 15000.0 2024-02-01           27.3\n  韩梅    前端实习生  8000.0 2024-06-01           23.4\n\n总人数: 18\n\n============================================================\n📈 线性回归分析结果\n============================================================\n  回归方程:  薪资 = 378.66 × 司龄(月) + 5440.11\n  斜率(β₁):  378.66 元/月 （每多工作1个月，薪资平均增加 ¥378.66）\n  截距(β₀):  ¥5440.11\n  相关系数 r:  0.9447\n  决定系数 R²:  0.8925 （模型解释了 89.3% 的薪资变异）\n  P值:          0.000000\n  RMSE:         ¥3362.94\n  MAE:          ¥2798.59\n\n  ✅ 结论: P值(0.000000) < 0.05，司龄对薪资的线性影响 **统计显著**\n\n============================================================\n🔮 薪资预测示例\n============================================================\n  司龄 12 个月 (≈1.0年) → 预测薪资: ¥9,984.07\n  司龄 24 个月 (≈2.0年) → 预测薪资: ¥14,528.03\n  司龄 36 个月 (≈3.0年) → 预测薪资: ¥19,072.00\n  司龄 48 个月 (≈4.0年) → 预测薪资: ¥23,615.96\n  司龄 60 个月 (≈5.0年) → 预测薪资: ¥28,159.92\n\n============================================================\n📊 残差分析（实际值 vs 预测值）\n============================================================\nname  salary    predicted     residual\n  陈刚 50000.0 46108.566068  3891.433932\n  张明 45000.0 43306.456549  1693.543451\n  王芳 35000.0 37285.707717 -2285.707717\n  钱伟 30000.0 36073.984682 -6073.984682\n  孙红 28000.0 33612.672266 -5612.672266\n  周明 32000.0 30545.498333  1454.501667\n  王强 30000.0 27667.656124  2332.343876\n  张伟 28000.0 24335.417777  3664.582223\n  陈静 20000.0 22214.902465 -2214.902465\n  李娜 22000.0 20586.649636  1413.350364\n  赵敏 24000.0 19942.921774  4057.078226\n  杨帆 19000.0 19374.926601  -374.926601\n  刘洋 23000.0 18314.668945  4685.331055\n  郑浩 17000.0 17860.272807  -860.272807\n  赵磊 16000.0 16686.416116  -686.416116\n  吴丽 18000.0 16004.821909  1995.178091\n  李强 15000.0 15777.623840  -777.623840\n  韩梅  8000.0 14300.836391 -6300.836391\n\n  残差均值:  ¥-0.00\n  残差标准差: ¥3460.44\n','',0,5117,'success',2,'2026-05-13 10:46:25'),(3,999,NULL,'\nimport pandas as pd\n\n# 查询各部门平均薪资\nquery = \"\"\"\nSELECT \n    d.name AS 部门名称,\n    COUNT(e.id) AS 员工数量,\n    ROUND(AVG(e.salary), 2) AS 平均月薪,\n    ROUND(MIN(e.salary), 2) AS 最低月薪,\n    ROUND(MAX(e.salary), 2) AS 最高月薪\nFROM employee e\nJOIN department d ON e.dept_id = d.id\nWHERE e.status = 1\nGROUP BY d.name\nORDER BY 平均月薪 DESC\nLIMIT 3\n\"\"\"\n\ndf = pd.read_sql(query, engine)\nprint(\"=== 薪资最高的3个部门 ===\")\nprint(df.to_string(index=False))\nprint()\n\n# 计算整体数据作为对比\noverall = pd.read_sql(\"\"\"\nSELECT \n    ROUND(AVG(salary), 2) AS 公司整体平均月薪\nFROM employee \nWHERE status = 1\n\"\"\", engine)\nprint(f\"📊 公司整体平均月薪: {overall[\'公司整体平均月薪\'][0]} 元\")\nprint(f\"📊 TOP3 部门平均薪资均值: {round(df[\'平均月薪\'].mean(), 2)} 元\")\nprint(f\"📊 高出公司均值: {round((df[\'平均月薪\'].mean() - float(overall[\'公司整体平均月薪\'][0])) / float(overall[\'公司整体平均月薪\'][0]) * 100, 2)}%\")\n','=== 薪资最高的3个部门 ===\n部门名称  员工数量    平均月薪    最低月薪    最高月薪\n 技术部     1 50000.0 50000.0 50000.0\n 后端组     4 30500.0 23000.0 45000.0\n 财务部     1 30000.0 30000.0 30000.0\n\n📊 公司整体平均月薪: 25555.56 元\n📊 TOP3 部门平均薪资均值: 36833.33 元\n📊 高出公司均值: 44.13%\n','',0,1190,'success',2,'2026-05-13 11:07:14'),(4,14,NULL,'\nimport pandas as pd\nimport matplotlib\nmatplotlib.use(\'Agg\')\n\n# 从数据库读取员工和部门数据\nemp_df = pd.read_sql(\"\"\"\n    SELECT e.name AS employee_name, e.salary, e.position, e.status, e.dept_id,\n           d.name AS dept_name\n    FROM employee e\n    LEFT JOIN department d ON e.dept_id = d.id\n\"\"\", engine)\n\n# 只看在职员工\nactive_df = emp_df[emp_df[\'status\'] == 1].copy()\n\nprint(\"=\" * 50)\nprint(\"📊 各部门平均薪资分析报告\")\nprint(\"=\" * 50)\n\n# 各部门薪资统计\ndept_stats = active_df.groupby(\'dept_name\')[\'salary\'].agg(\n    人数=\'count\',\n    平均薪资=\'mean\',\n    最高薪资=\'max\',\n    最低薪资=\'min\',\n    薪资中位数=\'median\',\n    薪资标准差=\'std\'\n).round(2).sort_values(\'平均薪资\', ascending=False)\n\nprint(\"\\n1️⃣ 各部门薪资统计表：\")\nprint(dept_stats.to_string())\n\n# 全公司汇总\nprint(f\"\\n2️⃣ 全公司汇总：\")\nprint(f\"   在职总人数：{len(active_df)} 人\")\nprint(f\"   全司平均薪资：{active_df[\'salary\'].mean():.2f} 元\")\nprint(f\"   全司薪资中位数：{active_df[\'salary\'].median():.2f} 元\")\nprint(f\"   全司薪资标准差：{active_df[\'salary\'].std():.2f} 元\")\n\n# 各部门与全司均值对比\nprint(f\"\\n3️⃣ 各部门与全司均值对比：\")\navg_salary = active_df[\'salary\'].mean()\nfor dept, row in dept_stats.iterrows():\n    diff = row[\'平均薪资\'] - avg_salary\n    pct = (diff / avg_salary) * 100\n    icon = \"↑\" if diff > 0 else \"↓\"\n    print(f\"   {dept:8s}：{row[\'平均薪资\']:>9.2f} 元  ({icon} {abs(pct):.1f}%)\")\n\n# 最高薪和最低薪部门\nprint(f\"\\n4️⃣ 关键发现：\")\nprint(f\"   🏆 最高平均薪资部门：{dept_stats.index[0]}（{dept_stats.iloc[0][\'平均薪资\']:.2f} 元）\")\nprint(f\"   📉 最低平均薪资部门：{dept_stats.index[-1]}（{dept_stats.iloc[-1][\'平均薪资\']:.2f} 元）\")\nprint(f\"   📊 薪资差异倍数：{dept_stats.iloc[0][\'平均薪资\'] / dept_stats.iloc[-1][\'平均薪资\']:.2f} 倍\")\n','==================================================\n📊 各部门平均薪资分析报告\n==================================================\n\n1️⃣ 各部门薪资统计表：\n           人数      平均薪资     最高薪资     最低薪资    薪资中位数     薪资标准差\ndept_name                                                   \n技术部         1  50000.00  50000.0  50000.0  50000.0       NaN\n后端组         4  30500.00  45000.0  23000.0  27000.0  10148.89\n财务部         1  30000.00  30000.0  30000.0  30000.0       NaN\n人力资源部       1  28000.00  28000.0  28000.0  28000.0       NaN\n产品部         2  25000.00  32000.0  18000.0  25000.0   9899.49\n销售部         3  22000.00  35000.0  15000.0  16000.0  11269.43\n测试组         2  19500.00  20000.0  19000.0  19500.0    707.11\n前端组         3  19333.33  28000.0   8000.0  22000.0  10263.20\n市场部         1  17000.00  17000.0  17000.0  17000.0       NaN\n\n2️⃣ 全公司汇总：\n   在职总人数：18 人\n   全司平均薪资：25555.56 元\n   全司薪资中位数：23500.00 元\n   全司薪资标准差：10556.42 元\n\n3️⃣ 各部门与全司均值对比：\n   技术部     ： 50000.00 元  (↑ 95.7%)\n   后端组     ： 30500.00 元  (↑ 19.3%)\n   财务部     ： 30000.00 元  (↑ 17.4%)\n   人力资源部   ： 28000.00 元  (↑ 9.6%)\n   产品部     ： 25000.00 元  (↓ 2.2%)\n   销售部     ： 22000.00 元  (↓ 13.9%)\n   测试组     ： 19500.00 元  (↓ 23.7%)\n   前端组     ： 19333.33 元  (↓ 24.3%)\n   市场部     ： 17000.00 元  (↓ 33.5%)\n\n4️⃣ 关键发现：\n   🏆 最高平均薪资部门：技术部（50000.00 元）\n   📉 最低平均薪资部门：市场部（17000.00 元）\n   📊 薪资差异倍数：2.94 倍\n','',0,2616,'success',2,'2026-05-13 12:34:29'),(5,15,NULL,'\nimport pandas as pd\nimport matplotlib\nmatplotlib.use(\'Agg\')\n\n# 从数据库读取员工和部门数据\nemp_df = pd.read_sql(\"SELECT dept_id, salary, status FROM employee WHERE status = 1\", engine)\ndept_df = pd.read_sql(\"SELECT id, name AS dept_name FROM department\", engine)\n\n# 合并数据\ndf = emp_df.merge(dept_df, left_on=\'dept_id\', right_on=\'id\', how=\'left\')\n\n# 按部门分组计算平均薪资\nresult = df.groupby(\'dept_name\')[\'salary\'].agg(\n    平均月薪=(\'mean\'),\n    最高月薪=(\'max\'),\n    最低月薪=(\'min\'),\n    员工人数=(\'count\')\n).reset_index()\n\n# 按平均月薪降序排序\nresult = result.sort_values(\'平均月薪\', ascending=False).reset_index(drop=True)\nresult.index = result.index + 1  # 排名从1开始\nresult.index.name = \'排名\'\n\n# 格式化输出\nresult_display = result.copy()\nresult_display[\'平均月薪\'] = result_display[\'平均月薪\'].round(2)\nresult_display[\'最高月薪\'] = result_display[\'最高月薪\'].round(2)\nresult_display[\'最低月薪\'] = result_display[\'最低月薪\'].round(2)\n\nprint(\"=\" * 70)\nprint(\"📊 各部门平均薪资分析报告（仅统计在职员工）\")\nprint(\"=\" * 70)\nprint(result_display.to_string())\nprint()\nprint(f\"🏆 平均薪资最高部门: {result.iloc[0][\'dept_name\']} ({result.iloc[0][\'平均月薪\']:.2f} 元)\")\nprint(f\"📉 平均薪资最低部门: {result.iloc[-1][\'dept_name\']} ({result.iloc[-1][\'平均月薪\']:.2f} 元)\")\nprint(f\"💰 全公司在职平均薪资: {df[\'salary\'].mean():.2f} 元\")\nprint(f\"👥 全公司在职员工总数: {len(df)} 人\")\n','======================================================================\n📊 各部门平均薪资分析报告（仅统计在职员工）\n======================================================================\n   dept_name      平均月薪     最高月薪     最低月薪  员工人数\n排名                                            \n1        技术部  50000.00  50000.0  50000.0     1\n2        后端组  30500.00  45000.0  23000.0     4\n3        财务部  30000.00  30000.0  30000.0     1\n4      人力资源部  28000.00  28000.0  28000.0     1\n5        产品部  25000.00  32000.0  18000.0     2\n6        销售部  22000.00  35000.0  15000.0     3\n7        测试组  19500.00  20000.0  19000.0     2\n8        前端组  19333.33  28000.0   8000.0     3\n9        市场部  17000.00  17000.0  17000.0     1\n\n🏆 平均薪资最高部门: 技术部 (50000.00 元)\n📉 平均薪资最低部门: 市场部 (17000.00 元)\n💰 全公司在职平均薪资: 25555.56 元\n👥 全公司在职员工总数: 18 人\n','',0,1068,'success',2,'2026-05-13 12:41:47'),(6,15,NULL,'\nimport pandas as pd\nimport matplotlib.pyplot as plt\nimport matplotlib\nimport numpy as np\n\n# 设置中文字体，防止中文乱码\nmatplotlib.rcParams[\'font.sans-serif\'] = [\'SimHei\', \'DejaVu Sans\']\nmatplotlib.rcParams[\'axes.unicode_minus\'] = False\n\n# 1. 用 pandas 从数据库读取员工和部门数据\nemp_df = pd.read_sql(\"SELECT name, dept_id, salary, status FROM employee WHERE status = 1\", engine)\ndept_df = pd.read_sql(\"SELECT id, name AS dept_name FROM department\", engine)\n\nprint(\"📋 员工数据（前5行）：\")\nprint(emp_df.head())\nprint(f\"\\n在职员工总数: {len(emp_df)}\")\n\n# 2. 合并员工表与部门表\nmerged = emp_df.merge(dept_df, left_on=\'dept_id\', right_on=\'id\', how=\'left\')\n\n# 3. 按部门分组，计算平均薪资、人数\ndept_salary = (\n    merged.groupby(\'dept_name\')[\'salary\']\n    .agg([\'mean\', \'count\', \'sum\'])\n    .reset_index()\n    .rename(columns={\'dept_name\': \'部门\', \'mean\': \'平均薪资\', \'count\': \'人数\', \'sum\': \'薪资总额\'})\n    .sort_values(\'平均薪资\', ascending=True)  # 升序排列，柱状图从下到上\n    .reset_index(drop=True)\n)\n\ndept_salary[\'平均薪资\'] = dept_salary[\'平均薪资\'].round(2)\ndept_salary[\'薪资总额\'] = dept_salary[\'薪资总额\'].round(2)\n\nprint(\"\\n📊 各部门平均薪资统计：\")\nprint(dept_salary.to_string(index=False))\n\n# 4. 绘制水平柱状图\nfig, ax = plt.subplots(figsize=(12, 7))\n\ncolors = plt.cm.Blues(np.linspace(0.35, 0.9, len(dept_salary)))\nbars = ax.barh(dept_salary[\'部门\'], dept_salary[\'平均薪资\'], color=colors, edgecolor=\'white\', height=0.6)\n\n# 在柱子上标注数值和人数\nfor bar, val, count in zip(bars, dept_salary[\'平均薪资\'], dept_salary[\'人数\']):\n    ax.text(bar.get_width() + 300, bar.get_y() + bar.get_height()/2,\n            f\'¥{val:,.0f}  ({count}人)\',\n            va=\'center\', fontsize=11, fontweight=\'bold\', color=\'#333333\')\n\n# 添加全公司平均线\ncompany_avg = emp_df[\'salary\'].mean()\nax.axvline(x=company_avg, color=\'#E74C3C\', linestyle=\'--\', linewidth=1.5, alpha=0.8)\nax.text(company_avg + 200, len(dept_salary) - 0.3,\n        f\'全公司平均 ¥{company_avg:,.0f}\',\n        color=\'#E74C3C\', fontsize=10, fontweight=\'bold\')\n\n# 美化图表\nax.set_xlabel(\'平均月薪（元）\', fontsize=12, fontweight=\'bold\')\nax.set_title(\'各部门平均薪资排名\', fontsize=16, fontweight=\'bold\', pad=15)\nax.spines[\'top\'].set_visible(False)\nax.spines[\'right\'].set_visible(False)\nax.set_xlim(0, dept_salary[\'平均薪资\'].max() * 1.35)\nax.tick_params(axis=\'y\', labelsize=11)\n\n# 添加网格线\nax.grid(axis=\'x\', alpha=0.3, linestyle=\'--\')\nax.set_axisbelow(True)\n\nplt.tight_layout()\n\n# 5. 保存图表\nsave_path = \'/tmp/dept_salary_bar.png\'\nfig.savefig(save_path, dpi=150, bbox_inches=\'tight\', facecolor=\'white\')\nplt.close()\n\nprint(f\"\\n✅ 图表已保存至: {save_path}\")\n','📋 员工数据（前5行）：\n  name  dept_id   salary  status\n0   张伟        2  28000.0       1\n1   李娜        2  22000.0       1\n2   王强        3  30000.0       1\n3   赵敏        3  24000.0       1\n4   刘洋        3  23000.0       1\n\n在职员工总数: 18\n\n📊 各部门平均薪资统计：\n   部门     平均薪资  人数     薪资总额\n  市场部 17000.00   1  17000.0\n  前端组 19333.33   3  58000.0\n  测试组 19500.00   2  39000.0\n  销售部 22000.00   3  66000.0\n  产品部 25000.00   2  50000.0\n人力资源部 28000.00   1  28000.0\n  财务部 30000.00   1  30000.0\n  后端组 30500.00   4 122000.0\n  技术部 50000.00   1  50000.0\n\n✅ 图表已保存至: /tmp/dept_salary_bar.png\n','/var/folders/j4/czgrwyn517v0sk3vq44j06mc0000gn/T/smartquery_8969256019147362978.py:100: UserWarning: Glyph 24179 (\\N{CJK UNIFIED IDEOGRAPH-5E73}) missing from font(s) DejaVu Sans.\n  plt.tight_layout()\n/var/folders/j4/czgrwyn517v0sk3vq44j06mc0000gn/T/smartquery_8969256019147362978.py:100: UserWarning: Glyph 22343 (\\N{CJK UNIFIED IDEOGRAPH-5747}) missing from font(s) DejaVu Sans.\n  plt.tight_layout()\n/var/folders/j4/czgrwyn517v0sk3vq44j06mc0000gn/T/smartquery_8969256019147362978.py:100: UserWarning: Glyph 26376 (\\N{CJK UNIFIED IDEOGRAPH-6708}) missing from font(s) DejaVu Sans.\n  plt.tight_layout()\n/var/folders/j4/czgrwyn517v0sk3vq44j06mc0000gn/T/smartquery_8969256019147362978.py:100: UserWarning: Glyph 34218 (\\N{CJK UNIFIED IDEOGRAPH-85AA}) missing from font(s) DejaVu Sans.\n  plt.tight_layout()\n/var/folders/j4/czgrwyn517v0sk3vq44j06mc0000gn/T/smartquery_8969256019147362978.py:100: UserWarning: Glyph 65288 (\\N{FULLWIDTH LEFT PARENTHESIS}) missing from font(s) DejaVu Sans.\n  plt.tight_layout()\n/var/folders/j4/czgrwyn517v0sk3vq44j06mc0000gn/T/smartquery_8969256019147362978.py:100: UserWarning: Glyph 20803 (\\N{CJK UNIFIED IDEOGRAPH-5143}) missing from font(s) DejaVu Sans.\n  p