CREATE TABLE `sq_llm_config` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `model_code` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `model_name` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `api_url` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `api_key` varchar(500) COLLATE utf8mb4_unicode_ci NOT NULL,
  `max_tokens` int NOT NULL DEFAULT '4096',
  `temperature` decimal(3,2) NOT NULL DEFAULT '0.10',
  `is_default` tinyint NOT NULL DEFAULT '0',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '1-启用 0-禁用',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `model_code` (`model_code`)
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
